<"'!doctype html>
<html lang="es">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Rompe Ladrillos</title>
<style>
:root{color-scheme:dark;--bg:#0a1020;--panel:#121c32;--ink:#eef5ff;--muted:#a7b8d7;--cyan:#5de7ff;--pink:#ff6bb5}
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at 50% -10%,#20365d 0,transparent 55%),var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,Segoe UI,sans-serif;padding:22px}
main{width:min(100%,900px)}header{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:14px;flex-wrap:wrap}.brand{font-size:clamp(1.35rem,4vw,2rem);font-weight:850;letter-spacing:.02em}.brand span{color:var(--cyan)}.stats{display:flex;gap:10px;flex-wrap:wrap}.stat{background:#121c32;border:1px solid #2c3d5e;border-radius:12px;padding:7px 14px;color:var(--muted)}.stat b{color:var(--ink);margin-left:6px;font-variant-numeric:tabular-nums}
.shell{position:relative;background:#080e1c;border:1px solid #33476b;border-radius:18px;padding:10px;box-shadow:0 24px 80px #0008}canvas{display:block;width:100%;height:auto;aspect-ratio:800/520;border-radius:11px;touch-action:none;background:#0a1428}.overlay{position:absolute;inset:10px;display:grid;place-items:center;border-radius:11px;background:#07101dcc;text-align:center;padding:24px}.overlay[hidden]{display:none}.card{max-width:440px}.card h1{font-size:clamp(1.8rem,6vw,3.1rem);line-height:1.05;margin:0 0 12px}.card p{color:var(--muted);margin:0 0 22px}.button{border:0;border-radius:999px;background:linear-gradient(100deg,#5de7ff,#84f0c7);color:#061323;padding:12px 24px;font:800 1rem system-ui;cursor:pointer;box-shadow:0 6px 24px #5de7ff44}.button:hover{filter:brightness(1.1);transform:translateY(-1px)}.help{text-align:center;color:var(--muted);font-size:.9rem;margin:13px 0 0}.help kbd{display:inline-block;border:1px solid #3c5074;border-bottom-width:2px;border-radius:5px;padding:0 6px;color:var(--ink);font:inherit;margin:0 2px}
</style>
</head>
<body>
<main>
<header><div class="brand">ROMPE <span>LADRILLOS</span></div><div class="stats" aria-live="polite"><div class="stat">Puntos <b id="score">0</b></div><div class="stat">Nivel <b id="level">1 / 2</b></div><div class="stat">Vidas <b id="lives">♥ ♥ ♥</b></div></div></header>
<div class="shell"><canvas id="game" width="800" height="520" aria-label="Juego de romper ladrillos"></canvas><div class="overlay" id="overlay"><div class="card"><h1 id="title">¡A jugar!</h1><p id="message">Rompe todos los ladrillos y pasa los dos niveles. Mueve la pala con el ratón o las flechas.</p><button class="button" id="start">Empezar partida</button></div></div></div>
<p class="help"><kbd>←</kbd> <kbd>→</kbd> o <kbd>A</kbd> <kbd>D</kbd> para mover · Ratón para dirigir la pala · <kbd>Espacio</kbd> para lanzar o pausar</p>
</main>
<script>
(()=>{
const canvas=document.querySelector('"'#game'),ctx=canvas.getContext('2d'),overlay=document.querySelector('#overlay'),title=document.querySelector('#title'),message=document.querySelector('#message'),startBtn=document.querySelector('#start');
const W=canvas.width,H=canvas.height,paddle={w:112,h:13,x:344,y:480,speed:8},ball={x:400,y:460,r:8,vx:0,vy:0};
const palette=['#55d6ff','#70e0c2','#ffd166','#ff9f68','#ff6bb5'];let score=0,lives=3,level=1,bricks=[],running=false,launched=false,ended=false,last=0,keys={};
function buildBricks(){bricks=[];const rows=level===1?5:6,cols=10,gap=8,bw=67,bh=22,left=(W-(cols*bw+(cols-1)*gap))/2,top=66;for(let r=0;r<rows;r++)for(let c=0;c<cols;c++){let hp=level===2&&r<2?2:1;bricks.push({x:left+c*(bw+gap),y:top+r*(bh+gap),w:bw,h:bh,hp,color:palette[(r+(level===2?1:0))%palette.length]})}}
function resetBall(){launched=false;ball.x=paddle.x+paddle.w/2;ball.y=paddle.y-ball.r-2;ball.vx=0;ball.vy=0}
function newGame(){score=0;lives=3;level=1;paddle.x=(W-paddle.w)/2;buildBricks();resetBall();ended=false;running=true;overlay.hidden=true;updateHud();last=performance.now();requestAnimationFrame(loop)}
function updateHud(){document.querySelector('#score').textContent=score;document.querySelector('#level').textContent=level+' / 2';document.querySelector('#lives').textContent='♥ '.repeat(lives).trim()||'—'}
function serve(){if("'!launched&&running){launched=true;ball.vx=(Math.random()-.5)*4;ball.vy=-5.3}}
function finish(head,copy,button='"'Jugar otra vez'){running=false;ended=true;title.textContent=head;message.textContent=copy;startBtn.textContent=button;overlay.hidden=false}
function nextLevel(){if(level===1){level=2;buildBricks();paddle.x=(W-paddle.w)/2;resetBall();updateHud();title.textContent='¡Nivel 2"'!'"';message.textContent='Los ladrillos dorados necesitan dos golpes. ¡Sigue así"'!'"';startBtn.textContent='Continuar';overlay.hidden=false;running=false}else finish('¡Victoria"'!'"','Has limpiado los dos niveles. Puntuación final: '+score+'.')}
function movePaddle(x){paddle.x=Math.max(0,Math.min(W-paddle.w,x-paddle.w/2));if("'!launched)resetBall()}
function hitRectCircle(rect){const cx=Math.max(rect.x,Math.min(ball.x,rect.x+rect.w)),cy=Math.max(rect.y,Math.min(ball.y,rect.y+rect.h));return (ball.x-cx)**2+(ball.y-cy)**2<ball.r**2}
function update(dt){if(!running)return;const step=Math.min(dt/16.67,2);if(keys.ArrowLeft||keys.a||keys.A)paddle.x=Math.max(0,paddle.x-paddle.speed*step);if(keys.ArrowRight||keys.d||keys.D)paddle.x=Math.min(W-paddle.w,paddle.x+paddle.speed*step);if(!launched){ball.x=paddle.x+paddle.w/2;ball.y=paddle.y-ball.r-2;return}
ball.x+=ball.vx*step;ball.y+=ball.vy*step;if(ball.x<ball.r){ball.x=ball.r;ball.vx=Math.abs(ball.vx)}if(ball.x>W-ball.r){ball.x=W-ball.r;ball.vx=-Math.abs(ball.vx)}if(ball.y<ball.r){ball.y=ball.r;ball.vy=Math.abs(ball.vy)}
if(ball.vy>0&&ball.y+ball.r>=paddle.y&&ball.y-ball.r<=paddle.y+paddle.h&&ball.x>=paddle.x&&ball.x<=paddle.x+paddle.w){ball.y=paddle.y-ball.r;const offset=(ball.x-(paddle.x+paddle.w/2))/(paddle.w/2);const speed=Math.min(8.5,Math.hypot(ball.vx,ball.vy)+.12);ball.vx=offset*speed*.9;ball.vy=-Math.sqrt(speed*speed-ball.vx*ball.vx)}
for(let i=bricks.length-1;i>=0;i--){let b=bricks[i];if(hitRectCircle(b)){b.hp--;ball.vy=-ball.vy;if(b.hp<=0){bricks.splice(i,1);score+=level===1?10:15}else b.color='"'#fff';updateHud();break}}
if(ball.y-ball.r>H){lives--;updateHud();if(lives<=0)finish('Fin de la partida','Puntuación final: '+score+'. ¿Lo intentamos de nuevo?');else resetBall()}if("'!bricks.length)nextLevel()}
function draw(){ctx.clearRect(0,0,W,H);let grad=ctx.createLinearGradient(0,0,0,H);grad.addColorStop(0,'"'#101d37');grad.addColorStop(1,'#091225');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#ffffff0b';ctx.lineWidth=1;for(let x=40;x<W;x+=40){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=40;y<H;y+=40){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
for(const b of bricks){ctx.fillStyle=b.color;ctx.shadowColor=b.color;ctx.shadowBlur=12;roundRect(b.x,b.y,b.w,b.h,6);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#07132388';roundRect(b.x+2,b.y+2,b.w-4,b.h-4,4);ctx.fill();if(b.hp>1){ctx.fillStyle='#fff';ctx.font='bold 11px system-ui';ctx.textAlign='center';ctx.fillText('2',b.x+b.w/2,b.y+15)}}
ctx.shadowColor='#5de7ff';ctx.shadowBlur=18;ctx.fillStyle='#d8fbff';roundRect(paddle.x,paddle.y,paddle.w,paddle.h,7);ctx.fill();ctx.shadowBlur=0;ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fillStyle='#fff';ctx.shadowColor='#fff';ctx.shadowBlur=16;ctx.fill();ctx.shadowBlur=0;ctx.textAlign='center';ctx.fillStyle='#ffffff77';ctx.font='12px system-ui';if("'!launched&&running)ctx.fillText('"'ESPACIO PARA LANZAR',W/2,445)}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function loop(now){if("'!running)return;const dt=now-last;last=now;update(dt);draw();if(running)requestAnimationFrame(loop)}
startBtn.addEventListener('"'click',()=>{if(ended)newGame();else{running=true;overlay.hidden=true;last=performance.now();requestAnimationFrame(loop)}});
window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.key===' '){if("'!running){if(!ended){running=true;overlay.hidden=true;last=performance.now();requestAnimationFrame(loop)}}else serve()}});window.addEventListener('"'keyup',e=>keys[e.key]=false);
canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();movePaddle((e.clientX-r.left)*W/r.width)});canvas.addEventListener('pointerdown',()=>{if(running)serve()});
buildBricks();resetBall();draw();
})();
</script>
</body>
</html>
